-- PostgreSQL 18 prepjointree.c reduce_outer_joins is the reference: a
-- condition above an outer join that rejects the nullable side's NULLs
-- narrows the join, and EXPLAIN prints the narrower join.
CREATE TABLE a376 (id int, x int);
CREATE TABLE b376 (id int, y int);
CREATE TABLE c376 (id int, z int);
INSERT INTO a376 SELECT g, g % 7 FROM generate_series(1, 40) g;
INSERT INTO b376 SELECT g, g % 5 FROM generate_series(1, 30, 2) g;
INSERT INTO c376 SELECT g, g % 3 FROM generate_series(1, 20, 3) g;
ANALYZE a376;
ANALYZE b376;
ANALYZE c376;
EXPLAIN (COSTS OFF) SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y = 1;
SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y = 1 ORDER BY 1;
EXPLAIN (COSTS OFF) SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y > a376.x;
EXPLAIN (COSTS OFF) SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y IS NOT NULL;
EXPLAIN (COSTS OFF) SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y = 1 OR a376.x = 2;
EXPLAIN (COSTS OFF) SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE coalesce(b376.y, 0) = 1;
EXPLAIN (COSTS OFF) SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE abs(b376.y) = 1;
EXPLAIN (COSTS OFF) SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y IS NULL;
EXPLAIN (COSTS OFF) SELECT count(*) FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y = 1;
SELECT count(*) FROM a376 LEFT JOIN b376 ON a376.id = b376.id WHERE b376.y = 1;
SELECT * FROM a376 RIGHT JOIN b376 ON a376.id = b376.id WHERE a376.x = 1 ORDER BY 1;
SELECT * FROM a376 FULL JOIN b376 ON a376.id = b376.id WHERE b376.y = 1 ORDER BY 3;
SELECT * FROM a376 FULL JOIN b376 ON a376.id = b376.id WHERE a376.x = 1 ORDER BY 1;
SELECT * FROM a376 FULL JOIN b376 ON a376.id = b376.id WHERE a376.x = 1 AND b376.y = 1 ORDER BY 1;
SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id JOIN c376 ON c376.id = b376.id ORDER BY 1;
SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id LEFT JOIN c376 ON c376.id = b376.id WHERE c376.z = 1 ORDER BY 1;
SELECT * FROM a376 LEFT JOIN b376 ON a376.id = b376.id LEFT JOIN c376 ON c376.id = b376.id WHERE c376.z IS NULL ORDER BY 1 LIMIT 5;
SELECT * FROM a376 LEFT JOIN b376 USING (id) WHERE b376.y = 2 ORDER BY 1;
SELECT * FROM a376 FULL JOIN b376 USING (id) WHERE b376.y = 2 ORDER BY 1;
